.worktop{display:grid;grid-template-columns:1.55fr 1fr;align-items:start;gap:25px}.kitchen{border:2px solid var(--ink);border-radius:4px;overflow:hidden;background:var(--paper);box-shadow:6px 6px 0 #d2c5a9}.scene{position:relative;aspect-ratio:3/2;overflow:hidden;background:#d8bd8e}.scene img{width:100%;height:100%;object-fit:cover;display:block}.clock{position:absolute;left:18px;top:18px;border:2px solid var(--ink);border-radius:50%;background:var(--paper);width:77px;height:77px;display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:3px 3px 0 #173d4222}.clock b{font:27px Cookbook,Georgia,serif}.clock span{font-size:10px;letter-spacing:.1em;text-transform:uppercase}.scene-label{position:absolute;bottom:15px;right:15px;background:var(--paper);padding:8px 13px;font-size:12px;border:1px solid var(--ink);transform:rotate(-3deg)}.stations{display:grid;grid-template-columns:repeat(3,1fr);gap:0}.station{padding:17px 12px;border-top:2px solid var(--ink);min-width:0;text-align:center}.station+.station{border-left:1px solid var(--line)}.station h2{font:18px Cookbook,Georgia,serif;margin:0 0 8px}.duration{font-size:12px;margin-bottom:13px}.bar{height:8px;background:#e7dfcb;margin:10px 0;overflow:hidden;border-radius:8px}.bar span{display:block;height:100%;width:0;background:var(--red);transition:width .3s}.station.done .bar span{background:#517961}.state{min-height:35px;font-size:12px;line-height:1.4}.station button{width:100%;margin-top:7px;padding:8px 3px}
